var a=`1400-pavlova-new-zealand-style`;var n=`world-1400`;var t=`NZ`;var r=`oceania`;var s=8;var o=202;var h={en:`Pavlova New Zealand Style`,ua:`Павлова по-новозеландськи`};var l={en:`Pavlova New Zealand Style is a dish from New Zealand featuring pasteurized egg whites, white vinegar, cornstarch, whipping cream. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Павлова по-новозеландськи, страва кухні країни Нова Зеландія з такими основними складниками: пастеризовані яєчні білки, білий оцет, кукурудзяний крохмаль, вершки для збивання. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Whip pasteurized whites with gradually added caster sugar until very thick and glossy; fold in vinegar and cornstarch.`,ua:`Збийте пастеризовані білки з поступово доданим дрібним цукром до густої блискучої меренги; обережно введіть оцет і крохмаль.`,t:[`whipping`],m:12,i:[[`pasteurized-egg-whites`,210,`ml`],[`caster-sugar`,290,`g`],[`white-vinegar`,12,`ml`],[`cornstarch`,15,`g`]]},{en:`Heap the meringue into a tall round on parchment, creating a shallow well for cream and fruit; do not proof.`,ua:`Викладіть меренгу високим колом на пергаменті, зробивши заглиблення для вершків і фруктів; не вистоюйте.`,t:[`pre-shaping-dough`,`final-proofing`],m:10,i:[]},{en:`Bake the large meringue gently at 110–120°C, then cool in the switched-off oven for a crisp shell and soft center.`,ua:`Повільно випікайте велику меренгу при 110–120°C, потім остудіть у вимкненій духовці для хрусткої оболонки й м’якої серединки.`,t:[`baking`],m:90,i:[]},{en:`Cool the finished meringue completely in the switched-off oven with the door ajar before adding cream; do not refrigerate the bare shell.`,ua:`Повністю остудіть готову меренгу у вимкненій духовці з прочиненими дверцятами перед додаванням крему; саму основу не тримайте у холодильнику.`,t:[`garnishing`],m:75,i:[]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:7,i:[[`whipping-cream`,360,`ml`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`kiwi`,4,`pcs`],[`passion-fruit`,3,`pcs`]]}];var g={slug:a,id:n,country:`NZ`,region:r,servings:8,minutes:202,title:h,text:l,steps:d};export{t as country,g as default,n as id,o as minutes,r as region,s as servings,a as slug,d as steps,l as text,h as title};